	id    string
	login string
}

func (b AssignableBot) DisplayName() string {
	return b.Login()
}

func (b AssignableBot) ID() string {
	return b.id
}

func (b AssignableBot) Login() string {
	return b.login
}

func (b AssignableBot) Name() string {
	return ""
}

