			assert.Equal(t, tt.wantBranchConfig.MergeBase, branchConfig.MergeBase)
			if tt.wantBranchConfig.RemoteURL != nil {
				assert.Equal(t, tt.wantBranchConfig.RemoteURL.String(), branchConfig.RemoteURL.String())
			}
		})
	}
}

