}

func newCreateCmd() *cobra.Command {
	opts := &CreateOptions{}

	createCmd := &cobra.Command{
		Use:   "create",
		Short: "Create a Codespace",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
