	case err := <-tunnelClosed:
		if err != nil {
			return fmt.Errorf("tunnel closed: %v", err)
		}
	case err := <-connClosed:
		if err != nil {
			return fmt.Errorf("connection closed: %v", err)
		}
	}

	return nil
