		responseBody = io.TeeReader(responseBody, bodyCopy)
	}

	if opts.Template != "" {
		// TODO: reuse parsed template across pagination invocations
		var t *template.Template
		t, err = parseTemplate(opts.Template, opts.IO.ColorEnabled())
		if err != nil {
			return
		}

