	if s.stderrTTYOverride {
		return s.stderrIsTTY
	}
	if stderr, ok := s.ErrOut.(*os.File); ok {
		return isTerminal(stderr)
	}
	return false
}

func (s *IOStreams) TerminalWidth() int {
	defaultWidth := 80
	if s.stdoutTTYOverride {
		return defaultWidth
