			utils.Yellow("!"),
			utils.Bold(ghrepo.FullName(possibleFork)),
			"already exists")
	} else {
		fmt.Fprintf(out, "%s Created fork %s\n", greenCheck, utils.Bold(ghrepo.FullName(forkedRepo)))
	}

